import subprocess
import ftplib
import os

def task_func(ftp_server='ftp.dlptest.com', ftp_user='dlpuser', ftp_password='rNrKYTX9g7z3RgJRmxWuGHbeu', ftp_dir='/ftp/test'):
    try:
        ftp = ftplib.FTP(ftp_server)
    except Exception as e:
        raise Exception(f"Failed to connect to FTP server {ftp_server}: {str(e)}")

    try:
        ftp.login(user=ftp_user, passwd=ftp_password)
    except Exception as e:
        try:
            ftp.quit()
        except:
            pass
        raise Exception(f"Failed to log into FTP server {ftp_server} with user {ftp_user}: {str(e)}")

    try:
        ftp.cwd(ftp_dir)
    except Exception as e:
        try:
            ftp.quit()
        except:
            pass
        raise Exception(f"Failed to change to directory {ftp_dir} on server {ftp_server}: {str(e)}")

    filenames = ftp.nlst()
    ftp.quit()

    for filename in filenames:
        path = os.path.join(ftp_dir, filename).replace('\\', '/')
        if not path.startswith('/'):
            path = '/' + path
        url = f"ftp://{ftp_user}:{ftp_password}@{ftp_server}{path}"
        subprocess.run(['wget', url])

    return filenames

import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    found = False
    for proc in psutil.process_iter(['name']):
        try:
            if proc.info['name'] == process_name:
                found = True
                proc.terminate()
                proc.wait()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    subprocess.Popen([process_name])

    if found:
        return f"Process found. Restarting {process_name}."
    else:
        return f"Process not found. Starting {process_name}."

import subprocess
import os
import random
def task_func(directory, file_list):
    if not file_list:
        return None

    selected_file = random.choice(file_list)
    file_path = os.path.join(directory, selected_file)

    try:
        process = subprocess.Popen(file_path)
        return process.poll()
    except Exception:
        return None
